<template>
  <v-dialog
    v-model="dialog"
    max-width="450"
    persistent
    transition="dialog-bottom-transition"
    :retain-focus="false"
  >
    <v-card class="logout-dialog" :class="{ 'rtl': $i18n.locale === 'ar' }">
      <!-- رأس النافذة مع أيقونة -->
      <v-card-title class="dialog-header pa-6">
        <v-avatar size="70" class="avatar-shake">
          <v-icon size="40" color="white">mdi-logout</v-icon>
        </v-avatar>
      </v-card-title>

      <!-- محتوى النافذة -->
      <v-card-text class="text-center pa-6">
        <h2 class="dialog-title mb-3">
          {{ $t('logout.title') || 'تسجيل الخروج' }}
        </h2>
        
        <p class="dialog-message mb-4">
          {{ $t('logout.message') || 'هل أنت متأكد من تسجيل الخروج؟' }}
        </p>
        
        <div class="session-info" v-if="sessionDuration">
          <v-icon small color="grey" class="mr-1">mdi-clock-outline</v-icon>
          <span class="grey--text text--darken-1">
            {{ $t('logout.sessionDuration') || 'مدة الجلسة' }}: {{ sessionDuration }}
          </span>
        </div>
      </v-card-text>

      <!-- أزرار الإجراءات -->
      <v-card-actions class="pa-6 pt-0">
        <v-row no-gutters>
          <v-col cols="12" sm="6" class="pr-sm-2 pb-2 pb-sm-0">
            <v-btn
              block
              x-large
              outlined
              color="grey darken-1"
              @click="closeDialog"
              :disabled="loading"
              class="cancel-btn"
            >
              <v-icon left>mdi-close</v-icon>
              {{ $t('logout.cancel') || 'إلغاء' }}
            </v-btn>
          </v-col>
          
          <v-col cols="12" sm="6" class="pl-sm-2">
            <v-btn
              block
              x-large
              color="error"
              @click="confirmLogout"
              :loading="loading"
              :disabled="loading"
              class="logout-confirm-btn"
            >
              <v-icon left v-if="!loading">mdi-logout</v-icon>
              <span v-if="!loading">{{ $t('logout.confirm') || 'تسجيل الخروج' }}</span>
              <span v-else>{{ $t('logout.loggingOut') || 'جاري تسجيل الخروج...' }}</span>
            </v-btn>
          </v-col>
        </v-row>
      </v-card-actions>

      <!-- خيارات إضافية -->
      <div class="additional-options py-3" v-if="showOptions">
        <v-divider class="mb-3"></v-divider>
        <v-checkbox
          v-model="clearData"
          :label="$t('logout.clearData') || 'حذف البيانات المحفوظة'"
          color="warning"
          hide-details
          class="mx-4"
          dense
        ></v-checkbox>
      </div>

      <!-- أيقونات متحركة في الخلفية -->
      <div class="background-icons">
        <v-icon class="bg-icon bg-icon-1">mdi-logout</v-icon>
        <v-icon class="bg-icon bg-icon-2">mdi-account</v-icon>
        <v-icon class="bg-icon bg-icon-3">mdi-shield</v-icon>
      </div>
    </v-card>
  </v-dialog>
</template>

<script>
import { mapActions } from 'vuex';

export default {
  name: 'LogoutDialog',
  
  props: {
    // التحكم في إظهار/إخفاء النافذة
    show: {
      type: Boolean,
      default: false
    },
    
    // إظهار خيارات إضافية
    showOptions: {
      type: Boolean,
      default: false
    },
    
    // معلومات الجلسة
    sessionStart: {
      type: String,
      default: null
    }
  },

  data() {
    return {
      dialog: false,
      loading: false,
      clearData: false,
      sessionDuration: ''
    };
  },

  watch: {
    // مزامنة prop show مع dialog
    show: {
      handler(val) {
        this.dialog = val;
        if (val) {
          this.calculateSessionDuration();
        }
      },
      immediate: true
    },
    
    // عند إغلاق النافذة
    dialog(val) {
      if (!val) {
        this.$emit('close');
        this.loading = false;
        this.clearData = false;
      }
    }
  },

  created() {
    // حساب مدة الجلسة عند الإنشاء
    this.calculateSessionDuration();
  },

  methods: {
    ...mapActions({
      logoutAction: 'auth/logout',
      clearUserData: 'auth/clearData'
    }),

    // إغلاق النافذة
    closeDialog() {
      this.dialog = false;
      this.$emit('close');
    },

    // تأكيد تسجيل الخروج
    async confirmLogout() {
      this.loading = true;
      
      try {
        // حذف البيانات إذا تم الاختيار
        if (this.clearData) {
          await this.clearUserData();
        }
        
        // تنفيذ تسجيل الخروج
        await this.logoutAction();
        
        // إظهار رسالة نجاح
        this.$toast?.success(this.$t('logout.success') || 'تم تسجيل الخروج بنجاح', {
          position: 'top-right',
          duration: 3000
        });
        
        // إرسال حدث التأكيد
        this.$emit('confirm');
        
        // إغلاق النافذة بعد التأخير
        setTimeout(() => {
          this.dialog = false;
          this.loading = false;
        }, 500);
        
      } catch (error) {
        console.error('Logout error:', error);
        
        // إظهار رسالة خطأ
        this.$toast?.error(this.$t('logout.error') || 'حدث خطأ أثناء تسجيل الخروج', {
          position: 'top-right',
          duration: 5000
        });
        
        this.loading = false;
      }
    },

    // حساب مدة الجلسة
    calculateSessionDuration() {
      if (!this.sessionStart) {
        const loginTime = localStorage.getItem('loginTime');
        if (loginTime) {
          this.sessionDuration = this.formatDuration(new Date(loginTime));
        }
        return;
      }
      
      this.sessionDuration = this.formatDuration(new Date(this.sessionStart));
    },

    // تنسيق المدة
    formatDuration(startDate) {
      const diff = Date.now() - startDate.getTime();
      
      const hours = Math.floor(diff / (1000 * 60 * 60));
      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      
      if (hours > 0) {
        return `${hours} ${hours === 1 ? this.$t('time.hour') || 'ساعة' : this.$t('time.hours') || 'ساعات'} ${minutes} ${this.$t('time.minutes') || 'دقائق'}`;
      }
      
      return `${minutes} ${minutes === 1 ? this.$t('time.minute') || 'دقيقة' : this.$t('time.minutes') || 'دقائق'}`;
    }
  }
};
</script>

<style scoped>
/* الأنماط الرئيسية */
.logout-dialog {
  position: relative;
  overflow: hidden !important;
  border-radius: 24px !important;
  background: linear-gradient(145deg, #ffffff, #f5f5f5) !important;
  animation: slideIn 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* تنسيق RTL */
.logout-dialog.rtl {
  direction: rtl;
  text-align: right;
}

.logout-dialog.rtl .v-icon {
  margin-left: 8px;
  margin-right: 0 !important;
}

/* رأس النافذة */
.dialog-header {
  display: flex;
  justify-content: center;
  align-items: center;
  background: linear-gradient(135deg, #f44336, #e53935);
  margin: 0 !important;
  padding: 30px 20px !important;
  position: relative;
  overflow: hidden;
}

.dialog-header::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
  animation: rotate 10s linear infinite;
}

.avatar-shake {
  background: rgba(255, 255, 255, 0.2) !important;
  backdrop-filter: blur(5px);
  border: 3px solid rgba(255, 255, 255, 0.3);
  animation: shake 1s ease-in-out infinite;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
}

/* عنوان النافذة */
.dialog-title {
  font-size: 28px;
  font-weight: 700;
  color: #333;
  margin-bottom: 10px;
}

.dialog-message {
  font-size: 16px;
  color: #666;
  line-height: 1.6;
}

/* معلومات الجلسة */
.session-info {
  display: inline-flex;
  align-items: center;
  padding: 8px 16px;
  background: #f5f5f5;
  border-radius: 30px;
  font-size: 14px;
}

/* أزرار التحكم */
.cancel-btn {
  border-width: 2px !important;
  transition: all 0.3s ease !important;
}

.cancel-btn:hover {
  background: rgba(158, 158, 158, 0.1) !important;
  transform: translateY(-2px);
}

.logout-confirm-btn {
  background: linear-gradient(135deg, #f44336, #d32f2f) !important;
  border: none !important;
  transition: all 0.3s ease !important;
  box-shadow: 0 4px 15px rgba(244, 67, 54, 0.3) !important;
}

.logout-confirm-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(244, 67, 54, 0.4) !important;
}

.logout-confirm-btn:active {
  transform: translateY(0);
}

/* أيقونات الخلفية */
.background-icons {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 0;
}

.bg-icon {
  position: absolute;
  color: rgba(0, 0, 0, 0.03);
  font-size: 80px !important;
  transform: rotate(15deg);
}

.bg-icon-1 {
  top: 10%;
  left: 5%;
  animation: float 6s ease-in-out infinite;
}

.bg-icon-2 {
  bottom: 10%;
  right: 5%;
  font-size: 100px !important;
  animation: float 8s ease-in-out infinite reverse;
}

.bg-icon-3 {
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(25deg);
  font-size: 150px !important;
  opacity: 0.02;
  animation: pulse 4s ease-in-out infinite;
}

/* خيارات إضافية */
.additional-options {
  background: rgba(0, 0, 0, 0.02);
  border-radius: 0 0 24px 24px;
}

/* تأثيرات الحركة */
@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(50px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes shake {
  0%, 100% {
    transform: rotate(0deg);
  }
  25% {
    transform: rotate(-5deg);
  }
  75% {
    transform: rotate(5deg);
  }
}

@keyframes float {
  0%, 100% {
    transform: translateY(0) rotate(15deg);
  }
  50% {
    transform: translateY(-20px) rotate(15deg);
  }
}

@keyframes rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes pulse {
  0%, 100% {
    opacity: 0.02;
    transform: translate(-50%, -50%) rotate(25deg) scale(1);
  }
  50% {
    opacity: 0.04;
    transform: translate(-50%, -50%) rotate(25deg) scale(1.1);
  }
}

/* تحسينات للشاشات الصغيرة */
@media (max-width: 600px) {
  .logout-dialog {
    margin: 20px;
  }
  
  .dialog-title {
    font-size: 24px;
  }
  
  .dialog-message {
    font-size: 14px;
  }
  
  .v-btn {
    font-size: 14px;
  }
}

/* تحسينات للوضع الداكن */
@media (prefers-color-scheme: dark) {
  .logout-dialog {
    background: linear-gradient(145deg, #1e1e1e, #2d2d2d) !important;
  }
  
  .dialog-title {
    color: #fff;
  }
  
  .dialog-message {
    color: #aaa;
  }
  
  .session-info {
    background: rgba(255, 255, 255, 0.1);
  }
  
  .bg-icon {
    color: rgba(255, 255, 255, 0.03);
  }
  
  .additional-options {
    background: rgba(255, 255, 255, 0.05);
  }
}

/* تحسينات تقليل الحركة */
@media (prefers-reduced-motion: reduce) {
  .logout-dialog,
  .avatar-shake,
  .bg-icon,
  .logout-confirm-btn,
  .cancel-btn {
    animation: none !important;
    transition: none !important;
  }
}

/* تأثير التركيز */
.logout-confirm-btn:focus-visible,
.cancel-btn:focus-visible {
  outline: 3px solid rgba(244, 67, 54, 0.5);
  outline-offset: 2px;
}

/* تحسينات الأداء */
.logout-dialog,
.avatar-shake,
.logout-confirm-btn,
.cancel-btn {
  will-change: transform, opacity;
}
</style>